import { User } from '../types';
import {
  getGlobalCliConfig,
  getLoggedInUser,
  updateUserDataAndPersist,
} from '../utils/config.util';
import logger, { withColor } from '../utils/logger.util';
import login from './login';
var Radio = require('prompt-radio');

const selectRegion = async (
  deafen = false,
): Promise<void | (typeof REGIONS)[number]> => {
  const log = deafen ? () => {} : logger.log;
  const prevConfig = getGlobalCliConfig();
  let userInfo = prevConfig?.user;
  if (!userInfo) {
    await login();
    userInfo = await getLoggedInUser();
    if (!userInfo) return log('you must be logged in to perform this action');
  }

  const regionChosen = await getRegionChoice(userInfo);
  if (!regionChosen) return log('action cancelled');

  log('\nupdating user settings...');

  const userUpdateRes = await updateUserDataAndPersist({
    defaultRegion: regionChosen.region,
  });

  if (userUpdateRes === 200) {
    log(`\ndefault db region - ${regionChosen.label} - saved successfully`);
    return regionChosen;
  }
};

export default selectRegion;

const REGIONS: {
  region: string;
  label: string;
}[] = [
  { label: 'americas (miami)', region: 'US_EAST' },
  { label: 'asia (delhi)', region: 'INDIA' },
  { label: 'europe (frankfurt)', region: 'EU_CENTRAL' },
];

export const getRegionChoice = async (userInfo: User) => {
  const defaultIndex = REGIONS.findIndex(
    (r) => r.region === userInfo.defaultRegion,
  );
  const regionSelectLabels = REGIONS.map(
    (r, i) =>
      r.label + (i === defaultIndex ? withColor(' current ', 'cyan') : ''),
  );
  const defaultLabel =
    defaultIndex >= 0 ? regionSelectLabels[defaultIndex] : undefined;

  const regionLabelChosen = await new Radio({
    name: 'colors',
    message: `\nchoose region (space to select, enter to submit)`,
    choices: regionSelectLabels,
    default: defaultLabel,
  }).run();

  const regionChosen = REGIONS.find((r) => r.label === regionLabelChosen);

  return regionChosen;
};
